import React, { useEffect, useState } from "react";
import { Html5QrcodeScanner } from "html5-qrcode";

function QRcodeScanner() {
  const [result, setResult] = useState("");
  const [success, setSuccess] = useState(-1);
  const [qrBoxSize, setQrBoxSize] = useState({ width: 300, height: 300 });

  useEffect(() => {
    // Adjust QR box size based on screen width
    const updateQrBoxSize = () => {
      const screenWidth = window.innerWidth;
      if (screenWidth < 600) {
        // For smaller screens, use a smaller QR box
        setQrBoxSize({ width: 200, height: 200 });
      } else {
        // For larger screens, use the default QR box
        setQrBoxSize({ width: 300, height: 300 });
      }
    };

    // Initial size adjustment
    updateQrBoxSize();

    // Adjust size on window resize
    window.addEventListener("resize", updateQrBoxSize);

    function onScanSuccess(decodedText, decodedResult) {
      console.log(`Code matched = `, decodedResult.result);
      setResult(decodedResult.result.text);
      setSuccess(0);
    }

    function onScanFailure(error) {
      console.warn(`Code scan error = ${error}`);
    }

    const html5QrcodeScanner = new Html5QrcodeScanner(
      "reader",
      { fps: 10, qrbox: qrBoxSize },
      /* verbose= */ false
    );
    html5QrcodeScanner.render(onScanSuccess, onScanFailure);

    // Clean up on unmount
    return () => {
      html5QrcodeScanner.clear();
      window.removeEventListener("resize", updateQrBoxSize);
    };
  }, [qrBoxSize]); // Re-run effect if `qrBoxSize` changes

  return (
    <div style={{ padding: "20px", textAlign: "center" }}>
      <div id="reader" style={{ margin: "auto" }}></div>
      {success !== -1 && (
        <div
          style={{
            marginTop: "20px",
            padding: "10px",
            borderRadius: "20px",
            backgroundColor: "#f0f0f0",
            display: "inline-block",
          }}
        >
          <p style={{ wordWrap: "break-word" }}>{result}</p>
        </div>
      )}
    </div>
  );
}

export default QRcodeScanner;
